from pathlib import Path
import json,sys,datetime,hashlib,subprocess
R=Path(__file__).parent;n=int(sys.argv[1]);b=R/f'batch-{n:04d}';r=json.loads((b/'RECEIPT.json').read_text());assert r['status']=='VERIFIED';m=json.loads((b/'RECOVERY_MAPPING.json').read_text());state=json.loads(subprocess.check_output(['python3',str(R/'continue_backup.py'),'state','{}'],text=True));stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ');d=R/('checkpoint-'+stamp);d.mkdir(mode=0o700)
text=f"# YIOS Batch{n} verified recovery receipt\n\nStatus VERIFIED. Uploaded bytes: {r['uploaded_bytes']:,}; complete independently retrieved SHA-256 verified bytes: {r['independently_retrieved_bytes']:,}. Source mappings: {r['mapped_source_files']}.\n\nAll-in physical uploaded bytes before this MD: {state['uploaded_bytes_including_controls']:,}; independently verified bytes: {state['verified_bytes_including_controls']:,}. This MD is additional payload, counted by its separate CONTROL-UPLOAD/VERIFY receipts after complete independent readback. No duplicate/partial I/O is counted as new recovery coverage.\n\nAuthenticated owner kgk2930@gmail.com; approved private yios hierarchy. Actual namespace IDs, source paths, hashes, bytes and remote object IDs follow. Source stability and current owner/private/parent/size gates passed. No source deletion/move/cleanup, Git/PR/branch/stash/LFS/production mutation, payment or reset credit use by this backup. This is file-level cloud recovery; independent-machine disaster recovery and production ownership acceptance remain unproven.\n\n```json\n"+json.dumps({'receipt':r,'recovery_mapping':m,'cumulative_before_this_control':state},indent=2,ensure_ascii=False)+'\n```\n'
p=d/f'YIOS_BATCH_{n:04d}_VERIFIED_RECOVERY_{stamp}.md';p.write_text(text);p.chmod(0o400);print(json.dumps({'checkpoint_dir':str(d),'handoff_path':str(p),'handoff_bytes':p.stat().st_size,'handoff_sha256':hashlib.sha256(p.read_bytes()).hexdigest()}))
